        {
          "source": "transcript",
          "quote": "Scheduled job:\n{\n  \"command\": \"/home/user/shutdown.sh\",\n  \"enabled\": true,\n  \"id\": \"workspace-shutdown\",\n  \"run_at\": \"2026-11-15T01:59:00-08:00\"\n}"
